SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+00:00";
SET FOREIGN_KEY_CHECKS = 0;

-- Struktur tabel
--

CREATE TABLE `master_lm` (
  `id` int NOT NULL,
  `tahun_ajaran_id` int DEFAULT NULL,
  `mapel_id` int NOT NULL,
  `tingkat` int NOT NULL COMMENT 'Contoh: 7, 8, 9',
  `semester` enum('Ganjil','Genap') NOT NULL DEFAULT 'Ganjil',
  `kategori` enum('Tengah','Akhir') DEFAULT 'Akhir',
  `kode_lm` varchar(20) NOT NULL COMMENT 'Contoh: LM 1, LM 2',
  `deskripsi_lm` text,
  `status` enum('Aktif','Nonaktif') NOT NULL DEFAULT 'Aktif',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deskripsi_a` text COMMENT 'Sangat Baik',
  `deskripsi_b` text COMMENT 'Baik',
  `deskripsi_c` text COMMENT 'Cukup',
  `deskripsi_d` text COMMENT 'Perlu Bimbingan'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

